   "ps": [
    "ঈশ্বরচন্দ্র বিদ্যাসাগর ভারতের পশ্চিমবঙ্গের মেদিনীপুর জেলার বীরসিংহ গ্রামে ২৬শে সেপ্টেম্বর ১৮২০ সালে জন্মগ্রহণ করেন। তাঁর মূল নাম ঈশ্বরচন্দ্র বন্দ্যোপাধ্যায়। ‘বিদ্যাসাগর’ তাঁর উপাধি। তিনি ছিলেন কলকাতা সংস্কৃত কলেজের ছাত্র। তিনি প্রথমে সংস্কৃত ও পরে ইংরেজি ভাষায় পাণ্ডিত্য অর্জন করেন। দানশীলতার জন্য তিনি ‘দয়ার সাগর’ নামেও পরিচিত। একাধারে পণ্ডিত, শিক্ষাবিদ, সমাজ-সংস্কারক ও খ্যাতনামা লেখক হিসেবে প্রতিষ্ঠা লাভ করেছিলেন তিনি। সুশৃঙ্খল পদবিন্যাস, যথাযথভাবে যতিচিহ্ন প্রয়োগ এবং সাহিত্যিক গদ্য রচনার জন্য তাঁকে বাংলা গদ্যের জনক বলা হয়ে থাকে। বাংলা বর্ণমালাকে নতুন বিন্যাসে সাজিয়ে ১৮৫৫ সালে বিদ্যাসাগর প্রকাশ করেন শিশুপাঠ্য বই বর্ণপরিচয়। ভাষা শিক্ষাদানের ক্ষেত্রে এ বই আজও পথপ্রদর্শক বিবেচিত হয়। বেতাল পঞ্চবিংশতি, ব্যাকরণ কৌমুদী, শকুন্তলা, বিধবা বিবাহ প্রচলিত হওয়া উচিত কি না এতদ্বিষয়ক প্রস্তাব, সীতার বনবাস, ভ্রান্তিবিলাস প্রভৃতি তাঁর প্রধান গ্রন্থ। ঈশ্বরচন্দ্র বিদ্যাসাগর ১৮৯১ সালের ২৯শে জুলাই মৃত্যুবরণ করেন।"
   ]
