   "uddipok": "চুরির অভিযোগে কিছু লোক জনৈক ব্যক্তিকে চেয়ারম্যানের ইউনিয়ন পরিষদে হাজির করল। ঘটনার বিবরণ শুনে তিনি চৌকিদার আমজাদকে ডেকে নির্দেশ দিলেন বন্দিকে তার বাড়িতে রাখতে। ঘটনাক্রমে আমজাদ জানতে পারলেন, বন্দি ব্যক্তি আর কেউ নয়, সে দশ বছর আগে আমজাদের সন্তানকে সড়ক দুর্ঘটনা থেকে বাঁচিয়েছিল, নিজ গৃহে নিয়ে গিয়ে আহত সন্তানের সেবা করেছিল। কিন্তু আমজাদ নিজের ক্ষতি হবে ভেবে না চেনার ভান করে চুপ করে রইল।",
