   "uddipok": "মৌরি একদিন বাবার কাছে বায়না ধরে বোটানিক্যাল গার্ডেনে বেড়াতে যাবে। বাবা একদিন ওকে নিয়ে বেড়াতে গেলে সে ভীষণ খুশি হয়। নানা জাতের ফুল-ফলের গাছের সমারোহ দেখে সে অভিভূত হয়ে যায়। দীর্ঘদিন সে যেসব ফুল-ফলের নাম শুনেছে সেগুলো আজ নিজ চোখে দেখে খুবই আনন্দিত হয়। অবশেষে সিদ্ধান্ত নেয়—বাড়ির আঙিনায় ছোট একটা বাগান করবে। (বইয়ের অনুশীলনীর সৃজনশীল প্রশ্ন)",
