   "ga": "উদ্দীপকের মৌরির ভালোলাগার বিষয়ের সঙ্গে ‘ফুলের বিবাহ’ গল্পের সাদৃশ্য ব্যাখ্যা কর। — মৌরি নানা জাতের ফুল-ফলের গাছ দেখে অভিভূত হয়; ফুলের প্রতি তার কৌতূহল ও ভালোলাগা তাকে নিজে বাগান করার সিদ্ধান্তে পৌঁছে দেয়। ‘ফুলের বিবাহ’ গল্পের লেখকও ফুলবাগানে বসে ফুলের জগতে এতটাই ডুবে যান যে ফুলগুলোকে মানবরূপে দেখেন—তাদের বিয়ে, ঘটকালি, বাসর সব কল্পনা করেন। দুই ক্ষেত্রেই মূল বিষয় এক: ফুলের সৌন্দর্যের প্রতি গভীর ভালোলাগা ও মনোযোগী পর্যবেক্ষণ।",
   "gha": "“মৌরির মাঝে সৃষ্ট প্রতিক্রিয়াই যেন ‘ফুলের বিবাহ’ গল্পের মূল চেতনা।”—যুক্তিসহ বুঝিয়ে লিখ। — গল্পটির মূল চেতনা হলো প্রকৃতির প্রতি কৌতূহলী ও পর্যবেক্ষণশীল দৃষ্টিভঙ্গি এবং তার সৌন্দর্য উপলব্ধি। লেখক ফুলের নাম, গন্ধের তারতম্য, ফোটার সময়—সব খুঁটিনাটি লক্ষ করে হাস্যরসের মাধ্যমে উপস্থাপন করেছেন; শেষে ক্ষণস্থায়ী সৌন্দর্য থেকে তিনি জীবনের অনিত্যতাও উপলব্ধি করেন। মৌরির ক্ষেত্রেও ফুল দেখার আনন্দ শুধু দেখায় থেমে থাকেনি—সে নিজে বাগান করার সিদ্ধান্ত নিয়েছে, অর্থাৎ প্রকৃতিকে ভালোবেসে তাকে নিজের জীবনে ধারণ করেছে। তাই মৌরির প্রতিক্রিয়াই গল্পের মূল চেতনার প্রতিফলন।"
