   "h": "শব্দার্থ ও টীকা; পাঠ-পরিচিতি",
   "ps": [
    "শব্দার্থ ও টীকা: গর্ভের কলঙ্ক—সন্তান হিসেবে কলঙ্ক; গর্ভ হলো মায়ের পেট; যে ব্যক্তি বা বস্তুকে পরিবারে নেতিবাচক হিসেবে দেখা হয় তা হলো কলঙ্ক। সুদীর্ঘ পল্লববিশিষ্ট—বড়ো পাতাবিশিষ্ট; এখানে চোখের পাতা হিসেবে ব্যবহৃত হয়েছে। ওষ্ঠাধর—ওষ্ঠ এবং অধর, উপরের ও নিচের ঠোঁট। কিশলয়—গাছের নতুন পাতা। তর্জমা—অনুবাদ, এক ভাষা থেকে অন্য ভাষায় রূপান্তর। অস্তমান—ডুবন্ত, ডুবে যাচ্ছে এমন। অনিমেষ—অপলক, পলকহীন। উদয়াস্ত—উদয়+অস্ত, আবির্ভাব ও তিরোভাব। ছায়ালোক—ছায়া+আলোক। বিজন মহত্ত্ব—বিজন মানে জনশূন্য, মহত্ত্ব মানে মহৎ গুণ। তন্বী—ক্ষীণ ও সুগঠিত অঙ্গবিশিষ্ট। বাঁশারি—কাঁধের দুদিকে দুপ্রান্তে ঝুলিয়ে বোঝা বহনের বাঁশের ফালি। ঢেঁকিশালা—যে ঘরে ঢেঁকি রাখা হয়; ঢেঁকি হলো ধান থেকে চাল তৈরির লোকজ যন্ত্র। গার্হস্থ্য সচ্ছলতা—পারিবারিক দৈনন্দিন জীবনের সচ্ছলতা। মূক—বধির, বোবা। বিষাদশান্ত—দুঃখময় শান্ত অবস্থা। পূর্ণিমাতিথি—চাঁদের পরিপূর্ণ রূপ হওয়ার সময়। কন্যাভারগ্রস্ত পিতা-মাতা—যে পিতা-মাতার বিবাহযোগ্যা কন্যাসন্তানের বিয়ে হয়নি। কপোল—গাল। নেত্রপল্লব—চোখের পাতা। শুক্লাদ্বাদশী—চাঁদের বারোতম দিন।",
    "পাঠ-পরিচিতি: ‘সুভা’ গল্পটি রবীন্দ্রনাথ ঠাকুরের বিখ্যাত গল্পগুচ্ছ থেকে সংকলিত হয়েছে। বাকপ্রতিবন্ধী কিশোরী সুভার প্রতি লেখকের হৃদয় নিংড়ানো ভালোবাসা ও মমত্ববোধে গল্পটি অমর হয়ে আছে। সুভা কথা বলতে পারে না। মা মনে করেন, এ তার নিয়তির দোষ, কিন্তু বাবা তাকে ভালোবাসেন। আর কেউ তার সঙ্গে মেশে না, খেলে না। কিন্তু তার বিশাল একটি আশ্রয়ের জগৎ আছে। যারা কথা বলতে পারে না সেই পোষা প্রাণীদের কাছে সে মুখর। তাদের সে খুবই কাছের জন। আর বিপুল নির্বাক প্রকৃতির কাছে সে পায় মুক্তির সনদ। ‘সুভা’ গল্পের মাধ্যমে রবীন্দ্রনাথ ঠাকুর বিশেষ চাহিদাসম্পন্ন শিশুর মন ও চিন্তা, আবেগ ও অনুভূতির সূক্ষ্মতর দিকগুলো উপস্থাপন করেছেন। শিশুর এ ধরনের প্রতি সকলের মমত্বশীল দৃষ্টিভঙ্গি প্রসূতে সহায়তা করে এ গল্প।"
   ]
