    "শব্দার্থ ও টীকা: সৌকুমার্য—সৌন্দর্য। ঝঞ্ঝাবাতে—ঝঞ্ঝার বাতাসে। কুন্তলীন, কেশলীন—লেখকের আমলে জনপ্রিয় চুলে দেয়ার তেলের নাম। হাওয়ার শাড়ি—সূক্ষ্ম সুতোর শাড়ি; পাতলা শাড়ি। তণ্ডুল—চাল। কালিডর, মিল্ক অব রোজ, ভিনোলিয়া পাউডার—সৌন্দর্যবর্ধক সামগ্রী। দিব্যাঙ্গনা—স্বর্গের রূপসী; হুরপরি। শুভ্রনীলাম্বর—পরিষ্কার নীল আকাশ। সাশ্রুসজলনয়ন—জলভরা চোখ। আত্মপ্রশংসা—নিজের প্রশংসা।",
