 "songkhipto": [
  {
   "q": "‘আম-আঁটির ভেঁপু’ গল্পের সারসংক্ষেপ লেখ।",
   "a": "দরিদ্র হরিহর রায়ের দুই সন্তান অপু ও দুর্গা। এক সকালে অপু টিনের বাক্সের সামান্য সম্পত্তি নিয়ে খেলছিল; দুর্গা পটলিদের বাগান থেকে কুড়িয়ে পাওয়া কচি আম জারানোর জন্য ভাইকে দিয়ে লুকিয়ে তেল-নুন আনিয়ে দুজনে আম খায়। মা সর্বজয়া ফিরে এলে ধরা পড়ার ভয়ে অপু কথা ফাঁস করে দিলে দিদি তাকে কিল বসায়। দুপুরে হরিহর বাড়ি ফিরে পরিবারের দেনা-অভাবের কথা ওঠে; সদ্‌গোপদের মন্তর দেওয়া ও অন্য গ্রামে বাসের প্রস্তাব নিয়েও তার দ্বিধা দেখা যায়। দুর্গা লুকিয়ে বাড়ি ঢুকতে না পেরে কাঁঠালতলায় বসে রড়া ফলের বিচি গুনে ভাইয়ের জন্য ভাগ করে রাখে।"
  },
  {
   "q": "দুর্গার চরিত্র বর্ণনা কর।",
   "a": "দুর্গা দশ-এগারো বছরের দুরন্ত, স্নেহময়ী ও বুদ্ধিমতী মেয়ে। সে বাগান থেকে আম কুড়িয়ে এনে ভাইকে খাওয়ায়, মায়ের ভয়ে কৌশলে তেল আনায়, ধরা পড়লে বুদ্ধি করে কথা ঘোরায়। ভাই কথা ফাঁস করলে রাগে কিল বসালেও রড়া ফলের বিচি গুনে অপুর জন্য আলাদা করে রাখে—এতে তার ভাইয়ের প্রতি গভীর মমত্ব ফুটে ওঠে। দারিদ্র্যের মধ্যেও তার চঞ্চলতা ও আনন্দ শৈশবের চিরায়ত রূপ ধরে রেখেছে।"
  },
  {
   "q": "গল্পে হরিহর পরিবারের দারিদ্র্যের চিত্র লেখ।",
   "a": "হরিহর অন্নদা রায়ের বাড়িতে গোমস্তার কাজ করে—মাসে আট টাকা, তাও দু-তিন মাস অন্তর পায়। সেজ ঠাকরুনের ধার পাঁচ মাস ধরে শোধ হয়নি, রাধা বোষ্টমের বৌ দু’বেলা তাগাদা দিচ্ছে। ছেলের কাপড়ে দু-তিন জায়গায় সেলাই। বাড়ি বহুদিন মেরামত হয়নি—রোয়াক ভাঙা, কপাট ভাঙা, নারিকেলের দড়ি দিয়ে বাঁধা। তবু এই অভাবের মধ্যেই শিশুদের শৈশব আনন্দে কেটে যায়।"
  }
 ],
