   "a": "পাঠ-পরিচিতিতেও বলা হয়েছে, অপু ও দুর্গা হতদরিদ্র পরিবারের শিশু হলেও তাদের শৈশবে দারিদ্র্যের কষ্ট প্রধান হয়ে ওঠেনি। প্রকৃতির অফুরন্ত সম্পদ—কুড়িয়ে পাওয়া আম, রড়া ফলের বিচি, নাটা ফল—আর ভাই-বোনের খেলা ও কৌতূহল তাদের জগৎ ভরিয়ে রেখেছে। সামান্য জিনিসই তাদের কাছে মহামূল্যবান সম্পত্তি। শৈশবের এই আনন্দময় দৃষ্টিভঙ্গিই দারিদ্র্যকে পেছনে ফেলে দিয়েছে।"
