   "ga": "উদ্দীপকে ‘আম-আঁটির ভেঁপু’র কোন দিক ফুটে উঠেছে? ব্যাখ্যা কর। — উদ্দীপকে ফুটে উঠেছে গ্রামীণ দরিদ্র পরিবারের জীবনসংগ্রাম ও অভাবের দিকটি। মকবুলদের নিজের জমি নেই—বর্গাচাষ, কামলা, লাকড়ি কাটা করে কোনোমতে জীবন চলে। হরিহরের পরিবারেও একই চিত্র: মাসে আট টাকা আয় তাও অনিয়মিত, রাজ্যের দেনা, ছেলের কাপড়ে সেলাই, ভাঙা বাড়ি। দুই ক্ষেত্রেই দারিদ্র্য গ্রামজীবনের নিত্যসঙ্গী।",
   "gha": "“উদ্দীপকটি ‘আম-আঁটির ভেঁপু’ গল্পের মূলভাবকে কতটুকু ধারণ করে?”—যুক্তিসহ বুঝিয়ে লিখ। — আংশিকভাবে ধারণ করে। দারিদ্র্য ও সংগ্রামের দিকটি উদ্দীপকে আছে, যা গল্পের পটভূমি। কিন্তু গল্পের মূলভাব শুধু দারিদ্র্য নয়—দারিদ্র্যের মধ্যেও শিশুর আনন্দপূর্ণ শৈশব, ভাই-বোনের স্নেহ-দুরন্তপনা এবং প্রকৃতির সঙ্গে শিশুর গভীর সম্পর্ক। উদ্দীপকে শিশু বা প্রকৃতি-আনন্দের কোনো স্থান নেই; সেখানে পরিশ্রমী বড়দের টিকে থাকার লড়াই। গল্পে অপু-দুর্গার কাছে সামান্য আম, বিচি, খাপরার কুচিই মহামূল্যবান—এই বিস্ময় ও আনন্দই মূলভাব, যা উদ্দীপক ধারণ করতে পারেনি।"
