    "শেষাংশে রহমান নিজের দেশ উত্তর-আফগানিস্তানের পানশিরের গুণগান করে: সেখানে একটা আস্ত দুম্বা খেয়ে এক ঢোক পানি খেলে আবার খিদে পায়; শীতকালে দুই দিন, তিন দিন, পাঁচ দিন, সাত দিন ধরে বরফ পড়ে—লোহার বারকোশে আঙার জ্বালিয়ে ছাই ঢাকা দিয়ে কম্বলের তলায় চাপা দিয়ে জানালার ধারে বসে সেই বরফপতন দেখার আরামের বর্ণনা সে এত প্রাণঢালা ভঙ্গিতে দেয় যে লেখক রাজি হয়ে যান—শীতকালটা পানশিরেই কাটাবেন। তবে শেষে হাস্যরসের মোড়: রহমান ভাবল হুজুর তার খুশির জন্য যাচ্ছেন; লেখক বুঝিয়ে বলেন—তোমার খুশির জন্য নয়; তুমি সমস্ত শীতকাল জানালার পাশে বসে কাটালে আমার রান্না করবে কে? অর্থাৎ যাচ্ছি আমার প্রাণ বাঁচাবার (খাওয়ার) জন্য!"
