   "h": "শব্দার্থ ও টীকা; পাঠ-পরিচিতি",
   "ps": [
    "শব্দার্থ ও টীকা: ও রভোয়া—ফরাসি ভাষার বাক্যবন্ধ; অর্থ: আবার দেখা হবে। নরদানব—মানুষের মতো দেখতে ভয়ঙ্কর জন্তু; এখানে বিশালদেহী মানুষ বোঝানো হয়েছে, আদরার্থে। মর্তমান কলা—মায়ানমারের মার্তবান দ্বীপে উৎপন্ন কলার জাত। রুজ—গাল রাঙানোর প্রসাধনী। পান্থুয়া—চিনির রসে ভেজানো ঘিয়ে ভাজা রসগোল্লা জাতীয় মিষ্টি। তাগদ—শক্তি। তর্ষী—তিরস্কার। বারকোশ—কাঠের তৈরি কানা উঁচু বড় থালা। পুনরপি—পুনরায়। ব্রহ্মরন্ধ্র—তালুর কেন্দ্রবর্তী ছিদ্র। বপু—বড় দেহ। তনু—ক্ষীণ দেহ। উত্তমার্থ—স্ত্রী, সহধর্মিণী।",
    "পাঠ-পরিচিতি: 'প্রবাস বন্ধু' সৈয়দ মুজতবা আলীর 'দেশে-বিদেশে' গ্রন্থের পঞ্চদশ পরিচ্ছেদ। প্রতিবেশী দেশ আফগানিস্তানের ভূমি, পরিবেশ, সেখানকার মানুষ ও তাদের সহজ-সরল জীবনাচরণ, বিচিত্র খাদ্য ইত্যাদি হাস্যরসাত্মকভাবে এই রচনায় ফুটিয়ে তোলা হয়েছে। লেখকের আফগানিস্তান বাসের আংশিক অভিজ্ঞতার পরিচয় আছে এখানে। আফগানিস্তানের রাজধানী কাবুলের সন্নিকটে খাজামোল্লা নামক গ্রামে বসবাসের সময় আবদুর রহমান নামের একজন তাঁর দেখভালের ছিলেন। আফগান আবদুর রহমান চরিত্রের মধ্যে সরলতা, স্বদেশপ্রেম, অতিথিপরায়ণতা ফুটে উঠেছে। আবদুর রহমানের রান্না ও পরিবেশন করা খাবারের মধ্যে আফগানিস্তানের বিচিত্র ও সুস্বাদু খাদ্যবস্তুর পরিচয় পাওয়া যায়। আফগানিস্তানের প্রস্তরভূমি এবং বরফ-শীতল জলবায়ু আকর্ষণীয়। 'প্রবাস বন্ধু' গল্পটি আমাদের দৃষ্টিকে প্রসারিত করে; একই সঙ্গে আন্তর্জাতিক প্রেক্ষাপটে জীবন ও জগৎ, সমাজ ও সংস্কৃতিকে ভাবতে শেখায়।"
   ]
