   "uddipok": "'এমন স্নিগ্ধ নদী কাহার, কোথায় এমন ধূম্র-পাহাড় / কোথায় এমন হরিংক্ষেত আকাশতলে মেশে। / এমন ধানের ওপর ঢেউ খেলে যায় বাতাস কাহার দেশে। / এমন দেশটি কোথাও খুঁজে পাবে নাকো তুমি / সকল দেশের রানি সে-যে আমার জন্মভূমি।' (বইয়ের অনুশীলনী)",
