   "kha": "'প্রবাস বন্ধু' রচনায় আবদুর রহমানকে 'নরদানব' বলা হয়েছে তার বিশাল ও ভয়ঙ্কর শারীরিক গঠনের জন্য। ফিতে দিয়ে মেপে সে ছ ফুট চার ইঞ্চি লম্বা, লম্বাই মিলিয়ে চওড়া; দুখানা হাত হাঁটু পর্যন্ত নেমে এসেছে, আঙুলগুলো যেন দু কাঁদি মর্তমান কলা, পা দুখানা ডিঙি নৌকার সাইজের। লেখকের ভাষায়, সে আমির আবদুর রহমান হলে অনায়াসে গোটা আফগানিস্তানের ভার বইতে পারত। তবে শব্দটি এখানে ঘৃণা অর্থে নয়, আদরার্থে ও বিস্ময় প্রকাশে ব্যবহৃত হয়েছে—এই বিশাল দেহের মানুষটিই ভীমসেনের মতো রান্না করে ও বিপদে মুশকিল-আসান হয়ে থাকে।",
