   "gha": "বিষয়বর্ণনায় সাদৃশ্য থাকলেও উদ্দীপক ও 'প্রবাস বন্ধু' ভ্রমণকাহিনির মধ্যে বিস্তর বৈপরীত্য রয়েছে—মন্তব্যটি যুক্তিসংগত। সাদৃশ্যের দিক হলো: দুটোতেই জন্মভূমির প্রকৃতির সৌন্দর্য বর্ণনা ও দেশের প্রতি গভীর মমত্ব প্রকাশ পেয়েছে। কিন্তু বৈপরীত্যগুলো মৌলিক। প্রথমত, উদ্দীপকে কবি বর্ণনা করেছেন নিজের দেশ বাংলাদেশের—স্নিগ্ধ নদী, হরিংক্ষেত, ধানক্ষেতের ওপর বাতাসের ঢেউ—অর্থাৎ সবুজ, স্নিগ্ধ, শস্যশ্যামল প্রকৃতি। অন্যদিকে 'প্রবাস বন্ধু'তে বর্ণিত প্রকৃতি বিদেশ আফগানিস্তানের পানশিরের—প্রস্তরভূমি, বরফ-শীতল জলবায়ু, সাত দিনব্যাপী বরফপাত—রুক্ষ ও কঠিন। দ্বিতীয়ত, উদ্দীপকের বর্ণনা কবির নিজের সরাসরি অভিব্যক্তি; কিন্তু প্রবাস বন্ধুতে পানশিরের বর্ণনা এসেছে অপরের (চাকর রহমানের) মুখে, আর লেখক সেখানে প্রবাসী শ্রোতা মাত্র। তৃতীয়ত, উদ্দীপকের ভাব আত্মতৃপ্তি ও গর্বের; প্রবাস বন্ধুতে তার সঙ্গে যুক্ত হয়েছে হাস্যরস ও চরিত্রচিত্রণ। সুতরাং বিষয় ও আবেগে মিল থাকলেও পটভূমি, প্রকৃতির রূপ, বর্ণনার ভঙ্গি ও উদ্দেশ্যে দুটি রচনা পরস্পরের বিপরীত।"
