    "কবি বলেন: আমি এই সুন্দর পৃথিবীতে মরতে চাই না; মানুষের মাঝেই বেঁচে থাকতে চাই। এই সূর্যের কিরণে, এই ফুলে ভরা বাগানে (পুষ্পিত কাননে) যদি জীবন্ত মানুষের হৃদয়ের মাঝে স্থান পাই! পৃথিবীতে প্রাণের খেলা চিরদিন তরঙ্গিত (বহমান)—বিরহ আর মিলন, কত হাসি আর অশ্রু। মানবের সুখে-দুঃখে গান বেঁধে (গাঁথিয়া সংগীত) যদি আমি অমর-আলয় (অমর সৃষ্টি) রচনা করতে পারি!",
    "তা যদি না পারি, তবে যতকাল বাঁচি, তোমাদের (মানুষের) মাঝখানেই যেন ঠাঁই পাই। তোমরা তুলবে বলে সকাল-বিকাল আমি নব নব সংগীতের কুসুম ফুটাই—অর্থাৎ মানুষের জন্য নিরন্তর নতুন নতুন সৃষ্টি করে যাই। হাসিমুখে আমার সেই ফুল (সৃষ্টি) গ্রহণ কোরো; আর তারপরে, যদি সে ফুল শুকিয়ে যায় (সৃষ্টি মূল্য হারায়), তবে ফেলে দিয়ো।",
