   "a": "দীঘির ঘাটে শ্যাওলা-পিছল নতুন সিঁড়ি জাগায় বধূ পা পিছলিয়ে জলে তলিয়ে যাওয়ার আশঙ্কা করে। পরক্ষণেই তার মনে হয়, ডুবে মরলে মন্দ হতো না—তাতে অন্ধত্বের অভিশাপ ঘুচে যেত, চোখ না-থাকার দ্বন্দ্ব-যন্ত্রণার চির অবসান ঘটত। এই চিন্তায় অন্ধত্বের কষ্টে তার জীবন কতটা ভারী হয়ে উঠেছে তা বোঝা যায়। তবে এটি তার ক্ষণিকের বিষণ্ণ ভাবনা মাত্র; সার্বিক চেতনায় সে জীবনপ্রেমী, নৈরাশ্যবাদী নয়।"
