   "a": "সাধারণ মানুষ দুঃখে-শোকে কাঁদে, আর কান্নার মধ্য দিয়ে তার দুঃখ-শোকের লাঘব ঘটে—এই অর্থে কাঁদা এক ধরনের 'সুখ' বা স্বস্তি। কিন্তু যার জন্ম থেকেই চোখ গেছে, কাঁদতে পেলে তার শোক কিছু কমত ঠিকই, তবু কান্না তার অন্ধত্ব ঘোচাতে পারে না। অর্থাৎ অন্যেরা কেঁদে হালকা হতে পারলেও জন্মান্ধের দুঃখ চিরস্থায়ী—কান্নার স্বস্তিটুকুও তার কাছে অর্থহীন, যেন বারণ। এতে বধূর দুঃখের চরম গভীরতা প্রকাশ পেয়েছে।"
