    "কবিতাটি পাহাড়ি ঝরনার আত্মকথন। ঝরনা বলে: আমি চপল (চঞ্চল) পায়ে কেবল ছুটি, কেবল পরীর গান গাই; পুলকে আমার সকল গা ও প্রাণ বিভোল (বিভোর)। শিথিল পাথরের ওপর দোদুল্য্যমান মনে চরণ ফেলি; দুপুর-ভোরে ঝিঁঝির ডাক শোনা যায়, পথ ঝিমায়, বন ঘুমায়। বিজন (নির্জন) দেশে পাখির কূজন নেই—নিজের পায়েই তাল বাজিয়ে একলা গাই, একলা ছুটি, দিবস-রাত, সাঁঝ-সকাল। ঘুম-পাহাড় ঘাড় ঝুঁকিয়ে ভয় দেখায়, চোখ পাকায়—কিন্তু আমার শঙ্কা নেই; টগর-ফুলের নূপুর পায়ে সমান বেগে এগিয়ে যাই। কোন গিরির হিম-ললাট ঘামল, কোন পরীর হার টুটল কোন নাচের উৎসবে—সে খেয়াল আমার নেই; আমি লীলায় ছুটি, খিলখিলিয়ে বুলবুলির বোল সাধি।",
