   "ka": "'জীবন বিনিময়' কবিতায় নিজের প্রাণ বা জীবনকে 'সবচেয়ে শ্রেষ্ঠ ধন' বলা হয়েছে—প্রত্যেক মানুষের কাছে নিজের জীবনই শ্রেষ্ঠ ধন হিসেবে বিবেচ্য।",
   "kha": "কবি 'জীবন বিনিময়' কবিতায় চিকিৎসকদের নীরবতাকে নিষ্ঠুর বলেছেন, কারণ সেই নীরবতা ছিল হুমায়ুনের মৃত্যুর নীরব ঘোষণা। বাবর বাষ্পকণ্ঠে ভিষকবৃন্দের কাছে জানতে চেয়েছিলেন—পুত্র এই রোগ থেকে মুক্তি পাবে কি না। জবাবে সবাই নতমস্তকে চুপ রইলেন। এই উত্তরহীনতাই বাবরকে বুঝিয়ে দিল, চিকিৎসকেরা আশা ছেড়ে দিয়েছেন। কবির ভাষায় তা 'শেলসম আসি বাবরের বুকে বিঁধিল'—তীক্ষ্ণ অস্ত্রের মতো আঘাত করল। মুখে না বলা এই সত্য মর্মান্তিক বলে নীরবতাকে 'নিষ্ঠুর' বলা হয়েছে।",
