   "h": "শব্দার্থ ও টীকা; পাঠ-পরিচিতি",
   "ps": [
    "শব্দার্থ ও টীকা: তাপ—উত্তাপ। হস্ত—হাত। পেরেশান—বিপর্যস্ত, ক্লান্ত। আমির উল-মুমেনিন—বিশ্বাসীদের নেতা; এখানে বিশেষভাবে বোঝানো হয়েছে মুসলমানদের ধর্মীয় প্রধান ও রাষ্ট্রীয় নেতা হজরত উমর (রা)-কে। মুয়াজ্জিন—যিনি আজান দেন। তকবির—'আল্লাহু আকবার' ধ্বনি বা রব। আখেরি—শেষ। পরশমণি—স্পর্শমণি, যার ছোঁয়ায় লোহাও সোনা হয়। তখত—সিংহাসন। সাইমুম—শুকনো উত্তপ্ত শ্বাসরোধকারী প্রবল হাওয়া, বিশেষত মরুভূমির হাওয়া। মশক—পানি বইবার চামড়ার থলে। দোর্রা—চাবুক। চীর—ছিন্ন বস্ত্র। পিরান—জামা। নান্দী—স্তুতি; কাব্যপাঠ বা নাটকের শুরুতে ছোট করে মঙ্গলসূচক প্রশস্তি পাঠ। শমশের—তরবারি।",
    "টীকা: উমর ফারুক—ইসলামের দ্বিতীয় খলিফা। তাঁর খেলাফতের সময়কাল দশ বছর (৬৩৪–৬৪৪ খ্রিস্টাব্দ)। তাঁর শাসনামলে ইসলামি রাষ্ট্রের সীমা আরব থেকে মিশর ও তুর্কিস্তানের সীমা পর্যন্ত প্রসারিত হয়। একজন ন্যায়নিষ্ঠ, নির্ভীক ও গণতন্ত্রমনা রাষ্ট্রনায়ক হিসেবে তাঁর খ্যাতি চির অম্লান। 'ফারুক' হজরত উমরের উপাধি; যিনি সত্য ও মিথ্যার মধ্যে পার্থক্য নিরূপণ করতে পারেন তাঁকেই 'ফারুক' বলা হয়। হজরত উমর (রা.) ছিলেন সত্যের একজন দৃঢ়চিত্ত উপাসক। 'তোমার স্মৃতি যে আজানের ধ্বনি জানে না মুয়াজ্জিন'—হজরত উমরের ইসলাম ধর্ম গ্রহণের পূর্বে নামাজের জন্য প্রকাশ্য আজান দেয়ার রীতি ছিল না; কোরেশদের ভয়ে মুসলমানরা উচ্চস্বরে আজান দিতে সাহস পেত না। উমর ছিলেন কোরেশ বংশোদ্ভূত শ্রেষ্ঠবীর; তিনি ইসলাম ধর্ম গ্রহণ করলে প্রকাশ্যে আজান দিতে আর কোনো বাধা রইল না। তাই আজানের সঙ্গে যে উমরের স্মৃতি বিজড়িত, সে কথা অনেক মুয়াজ্জিন জানে না। জেরুজালেম—ফিলিস্তিনের একটি প্রাচীন শহর। আবু শাহমা—হজরত উমরের পুত্র; মদপানের অপরাধে খলিফা তাঁকে ৮০টি বেত্রাঘাতের নির্দেশ দেন এবং নিজেই বেত্রাঘাত করেন; বেত্রাঘাতের ফলে আবু শাহমার মৃত্যু হয়।",
    "পাঠ-পরিচিতি: 'উমর ফারুক' কবিতাটি কাজী নজরুল ইসলামের 'জিঞ্জীর' কাব্য থেকে সংকলিত হয়েছে। কবিতাটিতে ইসলামের দ্বিতীয় খলিফা হজরত উমর (রা)-এর জীবনাদর্শ, চরিত্র-মাহাত্ম্য, মানবিকতা এবং সাম্যবাদী দৃষ্টিভঙ্গি সুন্দরভাবে প্রতিফলিত হয়েছে। খলিফা উমর (রা) ছিলেন একজন মহৎ ব্যক্তিত্ব। তাঁর চরিত্রে একাধারে বীরত্ব, কোমলতা, নিষ্ঠা এবং সাম্যবাদী আদর্শের অনন্য সমন্বয় ঘটেছিল। বিশাল মুসলিম রাষ্ট্রের সর্বাধিনায়ক হয়েও তিনি অতি সহজ, সরল, অনাড়ম্বর জীবনযাপন করেছেন। নিজ ভৃত্যকেও তিনি তাঁর সঙ্গে সমান মর্যাদা দিতে কুণ্ঠিত হননি। ন্যায়ের আদর্শ সমুন্নত রাখতে তিনি আপন সন্তানকে কঠোরতম শাস্তি দিতেও দ্বিধাবোধ করেননি। তিনি ছিলেন আমির-উল-মুমেনিন। রাসুলুল্লাহ (স.) তাঁকে আদর্শবান ব্যক্তিত্ব বলে বিশ্বাস করেই বলেছিলেন, তাঁর পরে যদি কেউ নবি হতেন, তাহলে তিনি হতেন উমর। মহৎপ্রাণ ও আদর্শ মানব চরিত্র অর্জনের জন্য উমর ফারুককে কবি উৎকৃষ্ট উদাহরণ হিসেবে কবিতায় উপস্থাপন করেছেন।"
   ]
