   "a": "জেরুজালেমের শত্রুপক্ষ শর্ত দেয়—খলিফা নিজে এসে সন্ধিপত্রে স্বাক্ষর করলে দুর্গের দ্বার খুলবে। আধেক পৃথিবীর মালিক উমর কোনো আড়ম্বর ছাড়াই একমাত্র ভৃত্যকে নিয়ে উটে চড়ে সাহারা পাড়ি দেন; সঙ্গে মাত্র দু-খানা শুকনো রুটি, মশকে পানি ও কয়েক মুঠি খোরমা। পথে ভৃত্য ক্লান্ত হয়ে পড়লে (তপ্ত বালুতে হেঁটে তার পায়ে রক্ত ফুটেছিল) উমর উট থেকে নেমে ভৃত্যকে উটে বসিয়ে নিজে রশি ধরে হাঁটতে থাকেন। ভৃত্যের আপত্তির উত্তরে তিনি বলেন, তিনি জনগণের প্রতিনিধি মাত্র—আরাম-সুখের অধিকার তাঁর নেই; ইসলামে সকলে সমান। ঘটনাটি তাঁর সাম্যবাদী চরিত্রের উজ্জ্বল দৃষ্টান্ত।"
