   "uddipok": "কাজী পাড়ার চেয়ারম্যান আব্বাস আলী। একবার তার নির্বাচনি এলাকার অধিকাংশ মানুষ ভয়াবহ বন্যায় আক্রান্ত হয়। কিন্তু বানভাসি মানুষ একদিনও চেয়ারম্যান সাহেবের দেখা পেলেন না। কারণ তিনি নাকি ঢাকায় জরুরি কাজে ব্যস্ত আছেন। অসহায় লোকগুলো খোলা আকাশের নিচে রোবা চাটনি মেলে অনাহারে-অর্ধাহারে দিন কাটায়। বন্যা শেষে একদিন আইন-শৃঙ্খলা রক্ষাকারী বাহিনী চেয়ারম্যানের বাগানবাড়ি তল্লাশি করে ত্রাণের প্রচুর টিন ও খাদ্যসামগ্রী উদ্ধার করে। (বইয়ের অনুশীলনী)",
