   "kha": "হজরত উমরকে 'আমিরুল মুমেনিন' বলা হয়, কারণ এর অর্থ 'বিশ্বাসীদের নেতা'। তিনি ইসলামের দ্বিতীয় খলিফা হিসেবে মুসলমানদের ধর্মীয় প্রধান ও রাষ্ট্রীয় নেতা ছিলেন। বিশাল মুসলিম জাহানের সর্বাধিনায়ক হিসেবে এই উপাধি তাঁর নেতৃত্ব ও কর্তৃত্বের স্বীকৃতি। কবিতায় কবিও তাঁকে বারবার 'আমির-উল-মুমেনিন' সম্বোধনে স্মরণ করেছেন—আধেক ধরার মালিক হয়েও তাঁর সাদামাটা জীবন ও সেবক-মনোভাব এই উপাধির মর্যাদা বাড়িয়ে দিয়েছে।",
   "ga": "চেয়ারম্যান আব্বাস আলী যেদিক থেকে হজরত উমরের সঙ্গে বৈসাদৃশ্যপূর্ণ, তা হলো দায়িত্ববোধ, মানবতা ও সততা। (১) উমর প্রজার দুঃখ শুনলে নিজে ছুটে যেতেন—নগর-ভ্রমণে বেরিয়ে ক্ষুধার্ত শিশুদের জন্য রাতেই বায়তুল-মালের খাদ্য নিজ পিঠে বয়ে পৌঁছে দিয়েছেন; আব্বাস আলী বন্যার পুরো সময় এলাকাতেই আসেননি, ঢাকায় 'জরুরি কাজে' থেকেছেন। (২) উমর রাষ্ট্রীয় সম্পদকে প্রজার আমানত মনে করতেন; আব্বাস ত্রাণের টিন ও খাদ্যসামগ্রী বাগানবাড়িতে গোপনে জমা করে আত্মসাতের চেষ্টা করেছেন। (৩) উমর নিজেকে প্রজার প্রতিনিধি ও সেবক মনে করতেন—ভৃত্যকেও উটে চড়িয়ে নিজে রশি ধরেছেন; আব্বাস ক্ষমতাকে ভোগের উপায় মনে করেন। অর্থাৎ উমর যেখানে সেবক-শাসকের আদর্শ, আব্বাস সেখানে তার সম্পূর্ণ বিপরীত—দায়িত্বহীন ও স্বার্থপর শাসকের ছবি।",
   "gha": "'উমর ফারুক' কবিতার আলোকে আব্বাস আলী চেয়ারম্যানকে উমরের মতো আদর্শ মানুষ হতে হলে তাঁকে করতে হবে: (১) জনপ্রতিনিধিত্বকে মালিকানা নয়, সেবা হিসেবে নেওয়া—উমরের ভাষায় 'আমি তোমাদের প্রতিনিধি শুধু'; ক্ষমতার আরাম-আয়েশ ছেড়ে প্রজার সুখ-দুঃখে পাশে দাঁড়াতে হবে। (২) দুর্গত মানুষের কাছে নিজে ছুটে যাওয়া—উমর যেমন নগর-ভ্রমণে প্রজার অবস্থা নিজ চোখে দেখতেন ও রাতেই খাদ্য পৌঁছে দিতেন; বন্যার সময় এলাকায় থেকে ত্রাণ নিজে তদারকি করা। (৩) ত্রাণ ও রাষ্ট্রীয় সম্পদের আমানতদারি—আত্মসাৎ নয়, বায়তুল-মালের মতো স্বচ্ছভাবে যোগ্য প্রাপকের কাছে পৌঁছে দেওয়া; উমর প্রয়োজনে নিজে বোঝা বয়েছেন। (৪) ন্যায়পরায়ণতা ও পক্ষপাতহীনতা—উমর নিজ পুত্রকেও শাস্তি দিতে দ্বিধা করেননি; আত্মীয়-স্বজন নয়, আইনের চোখে সবাই সমান—এই নীতি ধারণ করা। (৫) অনাড়ম্বর জীবন ও জবাবদিহির চেতনা—ভোগবিলাস ত্যাগ করে আল্লাহ ও জনগণের কাছে জবাবদিহির মানসিকতা রাখা। এসব গুণ অর্জন করলেই তিনি উমরের আদর্শের কাছাকাছি পৌঁছাতে পারবেন।"
