   "uddipok": "বিভূতিভূষণ বন্দ্যোপাধ্যায় তাঁর কথাসাহিত্যে প্রকৃতিকে একটি জীবন্ত চরিত্র হিসেবে সৃষ্টি করেছেন। বিশেষ করে 'পথের পাঁচালী' ও 'আরণ্যক' উপন্যাসে প্রকৃতি চিরকালের নবীনরূপে আবির্ভূত হয়েছে। অপু, দুর্গা এবং আরও অনেকে সেই চিরন্তন প্রকৃতির সন্তান। এরা যায়-আসে-থাকে না। কিন্তু প্রকৃতি চিরকালই নানা রূপ-রস-গন্ধ-বর্ণে বিরাজমান থাকে। (বইয়ের অনুশীলনী)",
