   "kha": "'পৃথিবীর এইসব গল্প বেঁচে রবে চিরকাল' বলতে কবি বুঝিয়েছেন, প্রকৃতির চিরায়ত সৌন্দর্য ও জীবনধারার গাঁথা কোনোদিন শেষ হবে না। মাঠের চঞ্চলতা, নক্ষত্রের তলে নদীর স্বপ্ন দেখা, শিশিরে চালতাফুল ভেজা ও তার নরম গন্ধের ঢেউ, লক্ষ্মীপেঁচার গান, চরে খেয়ানৌকার এসে লাগা—এই 'গল্প'গুলো ব্যক্তিমানুষের জন্ম-মৃত্যুর ঊর্ধ্বে। কবি নিজে চলে গেলেও, এমনকি সভ্যতা বিলীন হলেও, প্রকৃতির এই বহমান গল্প চিরকাল বেঁচে থাকবে—এই বিশ্বাসই পঙ্‌ক্তিটিতে ব্যক্ত হয়েছে।",
   "ga": "উদ্দীপকের প্রকৃতি-জ্ঞানের সঙ্গে 'সেইদিন এই মাঠ' কবিতার সাদৃশ্যপূর্ণ দিকটি হলো প্রকৃতির চিরন্তনতা বনাম মানুষের ক্ষণস্থায়িত্ব। বিভূতিভূষণের সাহিত্যে অপু, দুর্গা প্রভৃতি চরিত্র 'চিরন্তন প্রকৃতির সন্তান'—তারা যায়-আসে, থাকে না; কিন্তু প্রকৃতি চিরকাল নানা রূপ-রস-গন্ধ-বর্ণে বিরাজমান। জীবনানন্দের কবিতাতেও একই দৃষ্টি: কবি চলে যাবেন ('আমি চলে যাব বলে'), তবু মাঠ স্তব্ধ হবে না, চালতাফুল শিশিরে ভিজবে, লক্ষ্মীপেঁচা গান গাইবে। উভয় রচনাতেই মানুষ প্রজন্মের পর প্রজন্ম বদলায়, মরে; প্রকৃতি রয়ে যায় অনবদ্য, নবীন ও প্রাণময়। এই ভাবসাদৃশ্যই দুটি রচনাকে যুক্ত করেছে।",
   "gha": "কবিতায় উল্লিখিত সভ্যতার বিবর্তনের সঙ্গে প্রকৃতির সম্পর্ক উদ্দীপকের আলোকে বিশ্লেষণ করলে দেখা যায়, সম্পর্কটি বৈপরীত্যের। কবিতায় সভ্যতা ক্ষয়িষ্ণু: এশিরীয় সভ্যতা আজ ধুলো, বেবিলন ছাই—মানুষের নির্মাণ উজ্জ্বল হয়, আবার কালের স্রোতে বিলীন হয়; সভ্যতার চক্র উত্থান-পতনের। বিপরীতে প্রকৃতি শাশ্বত: বিবর্তনের মধ্যেও সে তার রূপ-রস-গন্ধ হারায় না, বরং প্রতিটি ঋতুতে নবীন হয়ে ওঠে। উদ্দীপকেও একই ছবি—বিভূতিভূষণের চরিত্রেরা (মানবপ্রজন্ম) যায়-আসে-থাকে না, কিন্তু প্রকৃতি চিরকালের নবীনরূপে পটভূমি হয়ে থাকে। অর্থাৎ সভ্যতা প্রকৃতির কোলে জন্মে, প্রকৃতিকে ব্যবহার করে গড়ে ওঠে, আবার প্রকৃতির ধুলোতেই মেশে; প্রকৃতি কিন্তু সেই সভ্যতার উত্থান-পতনের সাক্ষী হয়ে চিরকাল টিকে থাকে। মানুষের অহংকারের সীমা ও প্রকৃতির মহিমা—এই সত্যই উভয় রচনায় প্রতিফলিত।"
