    "গ্রামে গিয়ে কবি পাড়ার দস্যি ছেলেদের সঙ্গে দল বেঁধে খেলবেন; ধল-দীঘিতে সাঁতার কেটে রক্ত-কমল তুলবেন; শাপলা-লতায় চরণ জড়িয়ে ঢেউয়ের সঙ্গে দোল খাবেন; হিজল-ঝরা জলের ছিটায় গায়ের বরণ রঙিন হবে। পথে ফেলতে চরণে লাগবে মাটি-মার পরশ; পাখির সঙ্গে ভাব করবেন; অজানা ফুলের রূপ দেখে তাকে বিয়ের কনে মানবেন; চলতে পথে ময়না-কাঁটায় উত্তরীয় জড়িয়ে যাবে, টিল মাটির হোঁচটে আঁচল থেকে ফুল ঝরবে।",
