   "uddipok": "শহরের দুই বন্ধু শফিক ও আশিক পরিকল্পনা করে এবার গ্রীষ্মের ছুটিতে তাদের গ্রামের বন্ধু শাহেদের বাড়িতে যাবে। তারা কখনো গ্রাম দেখেনি। বইয়ের পাতায় আর টেলিভিশনে দেখেছে বহুবার, ভালোও লেগেছে কিন্তু সশরীরে যাওয়া হয়নি কখনো। তাই এ সুযোগ তারা কিছুতেই হাতছাড়া করবে না। তাদের ভালোলাগা আরও শতগুণ বেড়ে গেছে শাহেদ যখন নিজ গ্রামের বন-বনানী, ফুল, পাখি, দীঘি, শাপলা, মেঠো পথ, ছেলেমেয়েদের দুরন্তপনা ইত্যাদির নয়নাভিরাম বর্ণনা তাদের শুনিয়েছে। (বইয়ের অনুশীলনী)",
