   "kha": "কবিতায় গ্রাম্য মেয়ে পথে চলে মুঠি ভরে কদম-কলি ছড়াতে ছড়াতে—'তাহার পরে মুঠি ছড়িয়ে দিয়ে কদম-কলি, কোথাও মেলে বনে পাতা গ্রাম্য মেয়ে যায় যে চলি।' অর্থাৎ সে হাঁটতে হাঁটতে খেলার ছলে হাতের মুঠো থেকে কদমফুলের কলি ছড়িয়ে দেয়, কোথাও বনের পাতা মেলে (সরিয়ে) পথ করে এগিয়ে যায়। তার এই অনায়াস, স্বচ্ছন্দ চলায় পল্লিজীবনের সরলতা ও প্রকৃতির সঙ্গে গ্রাম্য মেয়ের সহজ আত্মীয়তা ফুটে উঠেছে।",
