   "uddipok": "কেউবা রঙিন কাঁথায় মেলিয়া বুকের স্বপনখানি, / তারে ভাষা দেয় দীঘল সুতায় মায়াবী আখর টানি। / আজিকে বাহিরে শুধু ক্রন্দন ছলছল জলধারে / বেণু-বনে বায়ু নীড়ে এলোকেশ, মন যেন চায় কারে। (বইয়ের অনুশীলনী)",
