   "kha": "কবি 'আমি কোনো আগন্তুক নই' বলেছেন জন্মভূমির সঙ্গে তাঁর আজন্ম ও অবিচ্ছেদ্য সম্পর্ক প্রমাণ করতে। তাঁর আশঙ্কা, কেউ হয়তো তাঁকে বহিরাগত বা ভিনদেশি পথিক ভাবতে পারে। কিন্তু তিনি এখানকারই সন্তান—এখানে ছিলেন, এখানেই থাকেন। দেশের প্রকৃতি (তারা, ফুল, জোনাকি, মাছরাঙা, ধানের মঞ্জরী) তাঁকে চেনে; তিনিও জনপদের মানুষের (কদম আলী, জমিলার মা) সুখ-দুঃখ চেনেন; তাঁর হাতে লেগে আছে লাঙল-বৈঠার স্পর্শ, শরীরে মাটির সুবাস। তাই খোদার কসম করে তিনি জোর দিয়ে বলেছেন—আমি কোনো আগন্তুক নই।",
