   "gha": "'উদ্দীপকের সঙ্গে আমি কোনো আগন্তুক নই কবিতার চেতনাগত বৈসাদৃশ্যই বেশি'—মন্তব্যটি যুক্তিসহ বিশ্লেষণ করলে দেখা যায়: (১) কালচেতনা: উদ্দীপকের কবি মৃত্যুর পরের কথা বলছেন—পুনর্জন্ম/রূপ বদলে 'আবার আসিব ফিরে' তাঁর ভবিষ্যৎ-আকাঙ্ক্ষা; তিনি এখন এই বাংলায় নেই বলেই ফেরার প্রশ্ন। বিপরীতে আহসান হাবীবের কবি বর্তমানেই এখানে আছেন—'আমি ছিলাম এখানে, এখানেই থাকি'—তাঁর দাবি অবিচ্ছিন্ন অবস্থানের, প্রত্যাবর্তনের নয়। (২) ভঙ্গি: উদ্দীপক সম্ভাবনামূলক ও স্বপ্নালু ('হয়তো দেখিবে', 'হয়তো শুনিবে')—অনিশ্চিত, মায়াময়; আগন্তুক-কবিতা দৃপ্ত ঘোষণামূলক ('খোদার কসম', 'আমাকে বিশ্বাস করো')—প্রমাণ ও যুক্তি দিয়ে দাবি প্রতিষ্ঠা করে। (৩) উপস্থিতির প্রমাণ: উদ্দীপকের কবিকে প্রকৃতির ভিড়ে 'খুঁজে পেতে' হয়; আহসান হাবীবের কবির হাতে-শরীরে মাটির স্পর্শ-গন্ধ লেগে থাকা জীবন্ত সাক্ষ্য হাজির। সুতরাং বাহ্যিক সাদৃশ্য (প্রকৃতিপ্রীতি) থাকলেও মূল চেতনায় একটি পুনর্জন্মের কল্পনাপ্রবণ, অন্যটি বর্তমান অস্তিত্বের দাবিদার—বৈসাদৃশ্যই প্রধান।"
