 "cq": [
  {
   "uddipok": "সামাদ সাহেব ব্যাংকে ক্যাশিয়ার হিসেবে ৩০ বছর যাবৎ কর্মরত আছেন। সবার আগে অফিসে আসেন এবং সবশেষে অফিস ত্যাগ করেন। একদিন ভাইয়ের মৃত্যুসংবাদ পেয়ে অপরাহ্ণে তিনি বাড়ি যান। পরদিন যথাসময়ে তিনি ফিরে আসেন। তাঁর কারণে কারো এতটুকু কষ্ট যাতে না হয় সে ব্যাপারে তিনি বেশ সচেতন। (বইয়ের অনুশীলনী)",
   "ka": "রানার ভোরে শহরে পৌঁছে যাবে—'শহরে রানার যাবেই পৌঁছে ভোরে।'",
   "kha": "'রাত নির্জন, পথে কত ভয়, তবুও রানার ছোটে'—রানার ছোটে তার দায়িত্ববোধের তাগিদে। তাকে ভোর হওয়ার আগেই শহরে পৌঁছে চিঠি ও সংবাদ পৌঁছে দিতে হবে; প্রিয়জনরা সেই খবরের অপেক্ষায় থাকে। পথে দস্যুর ভয়, অন্ধকার, দুর্গম পথ—কোনো কিছুই তার কাজের বাধা হতে পারে না। পাঠ-পরিচিতির ভাষায়, রানাররা এতটাই দায়িত্বশীল যে রাত হোক, দুর্গম পথ হোক, দুর্যোগপূর্ণ আবহাওয়া হোক—নিরন্তর তাদের এই কাজ করে যেতে হয়; যথাসময়ে খবর পৌঁছে দেওয়া অত্যন্ত জরুরি বলেই তারা ছোটে।",
   "ga": "উদ্দীপকের সামাদ সাহেবের মাঝে 'রানার' কবিতার রানার চরিত্রের সাদৃশ্যপূর্ণ দিকটি হলো কর্তব্যনিষ্ঠা ও দায়িত্বশীলতা। সামাদ সাহেব ত্রিশ বছর ধরে সবার আগে অফিসে আসেন, সবার শেষে যান; এমনকি ভাইয়ের মৃত্যুসংবাদের মতো ব্যক্তিগত শোকের দিনেও পরদিন যথাসময়ে ফিরে আসেন, যাতে তাঁর কারণে কারো কষ্ট না হয়। রানারও এমনই: রাত নির্জন, পথে দস্যুর ভয়, ঘরে অভাব ও প্রিয়ার অপেক্ষা—সব উপেক্ষা করে সে ভোরের আগে গন্তব্যে পৌঁছায়; তার চেয়ে বড় ভয় দায়িত্বে দেরি (সূর্য ওঠা)। উভয়ের কাছেই ব্যক্তিগত সুখ-দুঃখের ওপরে পেশাগত দায় বড়—এই দিকেই চরিত্র দুটির সাদৃশ্য।",
   "gha": "'সামাদ সাহেব রানার চরিত্রের বিশেষ দিককে ধারণ করলেও রানার স্বতন্ত্র'—মন্তব্যটি যথার্থ। সামাদ সাহেব ধারণ করেছেন রানারের একটি বিশেষ দিক—দায়িত্বশীলতা ও সময়নিষ্ঠা। কিন্তু রানার চরিত্র আরও বহুমাত্রিক ও স্বতন্ত্র: (১) দুর্ভোগের মাত্রা: রানারকে রাতের অন্ধকারে, দস্যুর ভয়ে, দুর্গম পথে শারীরিকভাবে ছুটতে হয়; ঘামে মাটি ভেজে, ক্লান্তশ্বাস আকাশ ছোঁয়—সামাদ সাহেবের কাজে এই কায়িক দুর্ভোগ নেই। (২) আর্থ-সামাজিক অবস্থা: রানার অভাবী শ্রমজীবী—ঘরে অভাব, পৃথিবী তার কাছে 'কালো ধোঁয়া'; তবু পিঠের টাকার বোঝা ছোঁয় না—এই সততা ও বঞ্চনা সামাদের চরিত্রে অনুপস্থিত। (৩) অবহেলা: রানারের নিজের দুঃখ কেউ জানে না—তার কথা ঢাকা থাকে কালো রাত্রির খামে; সামাদ সাহেবের দায়িত্ব অন্তত অফিসে দৃশ্যমান ও স্বীকৃত। (৪) প্রতীকী মাত্রা: কবিতার শেষে রানার শুধু ডাক-হরকরা নন, তিনি নতুন যুগের বার্তাবাহক—শপথের চিঠি নিয়ে অগ্রগতির খবর পৌঁছে দেওয়ার আহ্বান তাঁকে প্রতীকী মর্যাদা দিয়েছে, যা সামাদ সাহেবের ক্ষেত্রে প্রযোজ্য নয়। সুতরাং সামাদ একটি দিক ধারণ করলেও রানার চরিত্র সামগ্রিকভাবে স্বতন্ত্র ও গভীরতর।"
  }
 ]
