   "a": "উক্তিটি বহিপীরের—নিজের বইয়ের ভাষায় কথা বলার কারণ ব্যাখ্যা করতে গিয়ে হাতেম আলির প্রশ্নের জবাবে তিনি এটি বলেন। তাঁর যুক্তি: দেশের নানা স্থানে তাঁর মুরিদ, একেক স্থানে একেক রীতির ভাষা চালু—এক স্থানের জবান অন্য স্থানে বোধগম্য হয় না। তাই তিনি বইয়ের ভাষা রপ্ত করেছেন। তাঁর দাবি, কথ্য ভাষা মাঠঘাটের ভাষা—তাতে পবিত্রতা ও গাম্ভীর্য নেই; খোদার বাণী পৌঁছে দেওয়ার মতো উচ্চ কাজের উপযুক্ত একমাত্র পুস্তকের ভাষা। এই যুক্তির আড়ালে অবশ্য তাঁর আসল কৌশল—সাধারণ মানুষের কাছে নিজেকে রহস্যময় ও মহিমান্বিত করে তোলা, যাতে ধর্মব্যবসা সহজ হয়।"
