 "cq": [
  {
   "uddipok": "আজাদের বাবা নামকরা পির ছিলেন। কিন্তু আজাদ লেখাপড়া শিখেছেন। শহরে চাকরি করেন। দীর্ঘদিন পর গ্রামে বেড়াতে আসেন। গ্রামের মুরব্বি তার কাছে এসে তাকে সালাম করতে যায়। আজাদ সাহেব নিজেই তাকে সালাম করেন, নিজে মুরব্বিকে নিজেকে পাপী মনে করেন। আরেকজন তার কাছে পানি পড়া নিতে আসে। তাকে আজাদ সাহেব বোঝানোর চেষ্টা করেন। (বইয়ের অনুশীলনী)",
   "ka": "'বহিপীর' নাটকের প্রথম সংলাপটি হাশেম আলির—'কী ঝড়ই হলো শেষ রাতে! এমন ঝড় কখনো দেখিনি।'",
   "kha": "\"বিয়ে হলো তকদিরের কথা\"—কথাটি খোদেজার, তাহেরার পালানো প্রসঙ্গে। তাঁর বিশ্বাস, বিয়ে মানুষের ভাগ্যের লিখন; তা নিয়ে প্রশ্ন তোলা বা আপত্তি করা যায় না। কারও ভালো দুলা জোটে, কারও জোটে না—সবই তকদির। এই একটি বাক্যে সেকালের গ্রাম্য সমাজের দুটি মানসিকতা ধরা পড়ে: এক, নারীর নিজের মতামতের কোনো মূল্য নেই; দুই, অন্যায়কেও 'ভাগ্য' বলে মেনে নেওয়ার কুসংস্কারাচ্ছন্ন প্রবণতা। তাহেরার বিদ্রোহ আসলে এই মানসিকতার বিরুদ্ধেই।",
   "ga": "উদ্দীপকে বর্ণিত গ্রামের মানুষগুলোর কার্যক্রমে 'বহিপীর' নাটকে প্রতিফলিত সমাজের অন্ধ পির-ভক্তি ও কুসংস্কারের চিত্রকে ইঙ্গিত করা হয়েছে। উদ্দীপকে গ্রামের মুরব্বি আজাদকে তাঁর বাবার মর্যাদায় পির মনে করে পায়ে সালাম করতে যান; আরেকজন পানি পড়া নিতে আসে—অর্থাৎ জ্ঞান-বুদ্ধি নয়, বংশ ও অলৌকিকত্বেই তাদের আস্থা। নাটকের সমাজেও একই ছবি: গ্রামের সাধারণ মানুষ পিরকে পেলে হিতাহিত জ্ঞান হারিয়ে ফেলে—ধনসম্পদ থেকে শুরু করে নিজের কন্যা পর্যন্ত দান করে, তাঁর সেবা করার জন্য পাগল হয়ে যায়। তাহেরার বাবা-সৎমা পিরের মুরিদ বলেই মেয়েকে বৃদ্ধ পিরের হাতে তুলে দিয়েছেন। খোদেজাও পিরের অভিশাপের ভয়ে ভীত। অর্থাৎ দুই জায়গাতেই ধর্মের নামে অন্ধ আনুগত্যই মানুষের বিচারবুদ্ধিকে গ্রাস করেছে—এটাই নাট্যকারের দেখানো সমাজচিত্র।",
   "gha": "উদ্দীপকের আজাদ চরিত্রটি 'বহিপীর' নাটকের বহিপীরের মতো ধর্মব্যবসায়ী নয়—মন্তব্যটি যথার্থ। বহিপীর অশিক্ষিত সাধারণ মানুষের কুসংস্কার ও ধর্মান্ধতাকে পুঁজি করে ধর্মব্যবসা পরিচালনা করেন: সারা বছর মুরিদদের বাড়ি ঘুরে অর্থসম্পদ সংগ্রহ করেন, বইয়ের ভাষা ব্যবহার করে নিজেকে রহস্যময় করে তোলেন, প্রয়োজনে পুলিশের ভয়, ধর্মীয় দোহাই ও টাকার প্রলোভন—সব কৌশল প্রয়োগ করেন। অর্থাৎ ধর্ম তাঁর কাছে জীবিকা ও ক্ষমতার হাতিয়ার। আজাদ সম্পূর্ণ বিপরীত: পিরের ছেলে হয়েও তিনি পির-মর্যাদা প্রত্যাখ্যান করেন, মুরব্বিকে নিজে সালাম করেন, নিজেকে পাপী মনে করেন এবং পানি পড়ার কুসংস্কার ভাঙতে বোঝানোর চেষ্টা করেন। শিক্ষা তাঁকে অহংকার নয়, বিনয় ও যুক্তি দিয়েছে। তবে একটি সূক্ষ্ম দিকও আছে—নাটকের শেষে বহিপীর পরাজয় মেনে নিয়ে বিনা শর্তে সাহায্যের হাত বাড়ান, যা তাঁর ভেতরের মানবিকতার ঝলক। কিন্তু তাঁর পেশা ও পদ্ধতি আগাগোড়াই ধর্মব্যবসা; আজাদের সঙ্গে তাঁর মৌলিক পার্থক্য সেখানেই—একজন ধর্মকে বেচেন, অন্যজন ধর্মের নামে ব্যবসা করতেই অস্বীকার করেন।"
  }
 ]
